  "Adolfina": {
   "sources": [
    "https://github.com/nimda5/baltic-widgets/blob/codex/namedays-round4/research/namedays/round148-notes.json"
   ],
   "keep": true,
   "text": {
    "lv": [
     "Adolfina varētu būt vārda Ādolfs sieviešu forma. Vārdu Ādolfs parasti skaidro ar ģermāņu adal + wolf — «cēls + vilks». Tas ir pieņēmums: zināms tikai vārda izcelsmes virziens, bet ne tā tuvākā cilme."
    ],
    "ru": [
     "Adolfina, вероятно, женская форма имени Ādolfs. Имя Ādolfs обычно объясняют через германское adal + wolf — «благородный + волк». Это предположение: известно лишь общее направление происхождения имени, но не его ближайший источник."
    ],
    "en": [
     "Adolfina is probably a feminine form of Ādolfs. Ādolfs is usually explained from Germanic adal + wolf, “noble + wolf”. This is a hypothesis: only the general origin of the name is known, not its immediate source."
    ],
    "lt": [
     "Adolfina greičiausiai yra moteriška vardo Ādolfs forma. Vardas Ādolfs paprastai aiškinamas germanų adal + wolf („kilnus + vilkas“). Tai prielaida: žinoma tik bendra vardo kilmės kryptis, bet ne artimiausias šaltinis."
    ],
    "et": [
     "Adolfina on tõenäoliselt nime Ādolfs naisvorm. Nime Ādolfs seletatakse tavaliselt germaani sõnaga adal + wolf ‘õilis + hunt’. See on oletus: teada on vaid nime üldine päritolu, mitte selle lähim allikas."
    ]
   }
  },
